  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://luxespaformulas33.refersion.com/', 'official_site', 'affiliate', 'Luxe Spa Formulas'' official affiliate program agreement (run on Refersion) states verbatim in its Commissions section: ''There is no maximum commission limit.'' The same terms confirm affiliates earn commission on products purchased by their referrals, tracked through Refersion — commissions are explicitly uncapped.', 'verified', now());
