  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 8, 11, 7, 8, 3, '{"niche_fit": "Spa-grade firming and tightening skincare \u2014 a narrower, treatment-focused corner of the skincare niche.", "ugc_evidence": "A real, long-running affiliate program, but built on referral links rather than a creator or ambassador layer, so UGC-specific evidence is limited.", "compensation": "Commissions are explicitly uncapped in the program''s own terms (''There is no maximum commission limit''), with 8% per sale reported by affiliate roundups; the brand does not publish the percentage itself.", "contact_access": "A public application on the brand''s Refersion portal with review promised within 3 business days per roundups, but no published email.", "opportunity_availability": "Open to apply now through the Refersion portal.", "credibility": "Long-running niche brand (program terms date to 2018) with spa and dermatologist heritage, but a modest public footprint."}'::jsonb);
