  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/brands/halara', 'listing', 'affiliate', 'CollabFeed''s Halara creator program page states Halara runs an affiliate program joinable through ShareASale, Impact, Webgains, CJ or Admitad, paying 5 to 15% commission per referred order, paid monthly on net sales with a 30-day cookie, verified against the official page in September 2026.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/62847?setLocale=es_ES', 'listing', 'affiliate', 'Halara''s Awin UK programme profile states verbatim: ''We offer a competitive commission rate of up to 5% to 15% for each qualified sale.'' No statement about an earnings cap appears on the profile.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/brands/halara', 'listing', 'ugc_collab', 'CollabFeed has tracked only 9 paid partnership posts for Halara from 8 unique creators across Instagram, TikTok and YouTube, indicating a small tracked paid-creator footprint. A separate tracker (Sup) counts 469 creators collaborating in 12 months but explicitly includes organic posts alongside paid ones, so the paid-program footprint per CollabFeed remains low.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://referralrocket.io/affiliate-program/halara_SM', 'listing', 'general', 'Rate conflict flagged: third-party directories report different figures by network — up to 20% on ShareASale/Admitad and 12% for influencers on Impact (ReferralRocket), and a flat 8% on GetLasso — versus the 5-15% range published by CollabFeed and Awin. The recorded 15% is the top of the network-published range; creators should confirm the rate inside their chosen network.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 15, 8, 9, 4, '{"compensation": "Published 5-15% commission range across five networks plus Awin, paid monthly on net sales \u2014 the top of the range is competitive for fashion, though the exact rate varies by network.", "contact_access": "No published program contact email was found on fetched pages (CollabFeed masks it); access is through network applications only.", "credibility": "Large, well-known social-first athleisure brand with an established multi-network affiliate presence.", "niche_fit": "Athleisure and everyday fashion \u2014 exercise dresses, leggings, skirts \u2014 squarely in the fashion/fitness UGC try-on niche.", "opportunity_availability": "Open application today through six networks with approval typically within days.", "ugc_evidence": "A structured multi-network affiliate program aimed at influencers and content sites, plus a historically documented ambassador route with no follower minimum."}'::jsonb);
