  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sup.co/brands/lulus/creators', 'listing', 'ugc_collab', 'Sup recorded 611 creators collaborating with Lulus in 12 months and 1,350 total collaborations (organic and paid counted together) — a very large creator footprint, so saturation is recorded as high. The separate Lulus ambassador program has no application: representatives reach out to targeted influencers (NetInfluencer).', 'publicly_reported', now());
