  insert into public.brands (name, website, description, country, status) values ('Meshki', 'https://www.meshki.com.au', 'MESHKI is an Australian fashion brand founded in Sydney in 2013 by Shadi Kord and Natalie Khoei, which grew from an Instagram-led venture into an international online retailer built around glamorous styling and contemporary silhouettes — occasion dresses, eveningwear, bridal and bridesmaid styles, matching sets and knitwear.', 'Australia', 'published') returning id into bid;
