  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Meshki Affiliate Program (FlexOffers / Sovrn Commerce)', 'https://getlasso.co/affiliate/meshki/', 'https://getlasso.co/affiliate/meshki/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/meshki/', 'listing', 'affiliate', 'GetLasso''s MESHKI listing publishes a 6% per sale commission with a 30-day cookie and a join route through FlexOffers. Rates conflict across fetched sources: Shopper lists 5-10%, while Sovrn Commerce states MESHKI''s current rates ''could not be independently verified''. No earnings-cap statement appears on any fetched page.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ragtrader.com.au/news/how-200-led-to-2-million-followers-2000-influencers-and-social-sales-for-meshki', 'listing', 'ugc_collab', 'Ragtrader reported MESHKI ''has worked with more than 2000 influencers to date'' — a very large historical creator footprint, so saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/125093/meshki-affiliate-program', 'listing', 'general', 'Sovrn Commerce maintains a MESHKI merchant listing (founded Sydney 2013) but notes its current commission rates through Sovrn could not be independently verified — creators should confirm live terms inside the network before promoting. No official affiliate page on meshki.com.au was found.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 10, 6, 7, 4, '{"compensation": "A published 6% per sale via the FlexOffers route \u2014 modest, and other sources conflict (5-10% on Shopper, unverified on Sovrn).", "contact_access": "No program contact email on fetched pages (the brand''s hello@ address appears only as a competition organiser contact); access is via network listings.", "credibility": "Established Australian occasionwear brand founded in Sydney in 2013 with international reach and a two-million-follower Instagram presence.", "niche_fit": "Glamorous occasion and evening fashion \u2014 strong fit for event, bridal-party and going-out UGC.", "opportunity_availability": "Joinable through network listings (FlexOffers/Sovrn), but with no brand-published program page, availability is less direct than an official application.", "ugc_evidence": "The brand has a long influencer-led history (2,000+ influencers worked with per Ragtrader) and live network affiliate listings."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Alphalete', 'https://alphaleteathletics.com', 'Alphalete Athletics is a premium athletic wear and lifestyle brand founded by fitness influencer Christian Guzman, selling high-quality training apparel through its own store and regional sites, with its Alphaland gym and retail location in Missouri City, Texas.', 'United States', 'published') returning id into bid;
