  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/alphalete-athletics/.', 'https://alphaleteathletics.com/pages/alphalete-athlete-affiliate-application', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Alphalete Athlete & Affiliate Application (Impact)', 'https://alphaleteathletics.com/pages/alphalete-athlete-affiliate-application', 'https://alphaleteathletics.com/pages/alphalete-athlete-affiliate-application', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alphaleteathletics.com/pages/alphalete-athlete-affiliate-application', 'official_site', 'affiliate', 'Alphalete''s official application page distinguishes paid ''Athletes'' (exclusive long-term partners on monthly compensation) from ''Affiliates'' who earn commission on sales driven through their unique code; it states there is no strict follower minimum, that Instagram and TikTok are primary, and that review takes 7-10 business days. The official page publishes no commission rate and no earnings-cap statement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/alphalete-athletics/', 'listing', 'affiliate', 'LinkClicky''s Alphalete listing (last updated March 2024) publishes the program on Impact at 5% per sale across all regions. Because the figure is dated and the brand''s own page publishes no rate, creators should confirm the live rate inside Impact.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/alphalete-athletics-llc', 'listing', 'ugc_collab', 'Beacons Universe records 314 creators posting about Alphalete all time but only 3 sponsored posts in the last 12 months — a very small sponsored-creator footprint relative to the brand''s size, so saturation is recorded as low. NewCollab describes the collaboration type as gifted product plus affiliate commission, looking for around 500+ followers.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alphalete.uk/pages/faq', 'official_site', 'contact', 'Alphalete''s official FAQ publishes a partnerships route verbatim: ''We are always interested in exploring new partnerships & expanding our roster with Athletes and Affiliates… please email marketing@alphaleteathletics.com''.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 9, 13, 9, 4, '{"compensation": "Affiliates earn code-based commission \u2014 5% per sale per the Impact listing \u2014 but the brand''s own page publishes no rate, so the figure needs confirming in-network.", "contact_access": "A published partnerships email (marketing@alphaleteathletics.com) on the official FAQ plus a direct application form on the brand''s own domain \u2014 top band per the rubric.", "credibility": "Established premium fitness brand founded by a major fitness creator, with its own gym/retail destination in Texas.", "niche_fit": "Premium gym apparel built by a fitness influencer \u2014 squarely in the fitness UGC niche, with Instagram and TikTok named as primary platforms.", "opportunity_availability": "Open application form on the official site today, no strict follower minimum, with a stated 7-10 business day review.", "ugc_evidence": "A structured two-tier creator system (paid Athletes plus commission Affiliates) with an open application and published recruiting language."}'::jsonb);
