  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/mono-b/', 'listing', 'affiliate', 'LinkClicky''s Mono B listing (last updated March 2024) publishes the affiliate program on Impact at 15% per sale across all regions, with the join route into Impact. No program page exists on the brand''s own site and no earnings-cap statement appears on the listing, so the live terms should be verified inside Impact.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mymonob.com/pages/about-mono-b', 'official_site', 'general', 'Mono B''s official About page states it was ''Established in 2009 in the heart of Los Angeles'' fashion district'', is female-led and design-inspired with performance fabrics. No Beacons, CollabFeed or NewCollab creator counts were found for the brand, so saturation is recorded as unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 16, 6, 8, 3, '{"compensation": "A published 15% per sale on Impact \u2014 the highest published rate in this group \u2014 though it rests on a March 2024 listing and should be verified in-network.", "contact_access": "No published program contact email and no on-site program page; access is through the Impact listing only.", "credibility": "Operating since 2009 with a real LA fashion-district base, but substantially wholesale/B2B-oriented, which tempers its creator-program credibility.", "niche_fit": "Fashion-forward activewear and athleisure fits the fitness UGC niche, though the brand''s wholesale skew weakens the pure DTC creator fit.", "opportunity_availability": "Joinable today through Impact per the published listing, across all regions.", "ugc_evidence": "A live network affiliate listing exists, but there is no brand-published creator program or visible creator recruiting, so collaboration evidence is thin."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FP Movement', 'https://www.fpmovement.com', 'Established in 2012 as a category on Free People, FP Movement has been at the forefront of redefining activewear, introducing performance-ready styles that extend beyond the gym — its activewear for Hike, Run, Racquet, Studio and Ski bridges the gap between fashion and function, with 56 stores nationwide.', 'United States', 'published') returning id into bid;
