  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FP Movement Affiliate Program (Rakuten Advertising)', 'https://www.freepeople.com/fpmovement/help/affiliates/', 'https://www.freepeople.com/fpmovement/help/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.freepeople.com/fpmovement/help/affiliates/', 'official_site', 'affiliate', 'Free People''s official FP Movement affiliate page states: ''There''s an easy sign-up process through Rakuten Advertising, or you can connect with us directly if you''re already an established publisher. If you''re approved, all sales generated from your banners and posts will receive a commission.'' The brand publishes no rate and no earnings-cap statement on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/free-people/', 'listing', 'affiliate', 'Third-party rates conflict and neither is brand-published: UpPromote reports Free People commissions ''generally around 3% - 4%'' across Rakuten/CJ/FlexOffers, while Shopper lists 5-10%. The rate is therefore recorded as null rather than guessed.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ovotalent.com/learn/brand-ambassador-programs/', 'listing', 'ugc_collab', 'OVO Talent''s comparison notes FP Movement ambassadors are pro athletes — the ambassador tier is curated rather than an open creator pool — while the Rakuten affiliate program is the open route. No creator counts are published, so saturation is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 7, 6, 8, 5, '{"compensation": "Commission is confirmed by the brand but no rate is published on the official page, and third-party figures conflict (3-4% vs 5-10%) \u2014 scored conservatively with the rate recorded as null.", "contact_access": "No published program email; sign-up runs through Rakuten Advertising from the official page, with a direct route only for established publishers.", "credibility": "The activewear line of Free People (URBN), established 2012 with 56 stores nationwide \u2014 top-tier retail credibility.", "niche_fit": "Performance activewear across hike, run, racquet, studio and ski that bridges fashion and function \u2014 a strong fitness/fashion UGC fit.", "opportunity_availability": "Open affiliate sign-up via Rakuten today; the ambassador tier is reserved for pro athletes and is not open.", "ugc_evidence": "An official affiliate program page on the parent brand''s domain actively routing publishers into Rakuten, though creator-specific recruiting is limited."}'::jsonb);
