  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dagnedover.com/pages/affiliate-program', 'official_site', 'affiliate', 'Dagne Dover''s official affiliate page invites creators to ''earn up to 10% commission when your audience shops through your links'' within a 30-day attribution window, paid regularly through LTK; applicants must have a public social profile, an engaged audience and an LTK creator account, with applications reviewed weekly. No earnings-cap statement appears in the page''s FAQ.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/dagne-dover', 'listing', 'ugc_collab', 'Beacons Universe records posts from 515 creators all time for Dagne Dover, with 33 sponsored posts in the last 12 months — a large, active creator footprint, so saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/dagnedover-com-affiliate-program', 'listing', 'general', 'Directory figures differ slightly from the official page: Shopper lists 5-10% and Shopday describes commission as ''varies by partner'', versus the official ''up to 10%''. A separate Partnerize content-partner program also exists per a Partnerize case study, so creators should confirm which route they are accepted into.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 13, 8, 8, 4, '{"compensation": "A brand-published ''up to 10% commission'' with a 30-day attribution window and regular LTK payouts \u2014 solid for travel accessories.", "contact_access": "No published program email; application runs through the official page into LTK with a stated weekly review cycle.", "credibility": "Established New York bag brand with a documented affiliate operation across LTK and Partnerize.", "niche_fit": "Work, travel and everyday-carry bags \u2014 a core travel/lifestyle UGC category for packing and everyday-carry content.", "opportunity_availability": "Open application today via the official page, gated on a public profile, engaged audience and an LTK creator account.", "ugc_evidence": "An official creator-facing affiliate page with clear terms, plus 33 sponsored posts in the last 12 months per Beacons showing active creator collaboration."}'::jsonb);
