  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://huel.com/pages/club-huel-creator-programme', 'brand_website', 'creator_program_page', 'Official Club Huel page lists three ways to partner: CREATOR for social-first creators 5K+ followers on Instagram/TikTok at up to 15% commission with product vouchers, challenges and briefs; PRO for PTs/coaches/bloggers at up to 15%; STAR invite-only at up to 20%.', 'verified', now());
