  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ritual.com/pages/partner-with-us', 'brand_official_site', 'affiliate_program_page', 'Official Partner With Us page fetched in full: ''Affiliate Publications & Bloggers'' program operates on the Impact Affiliate Network; perks are commission for each sale from a unique link, custom audience discounts and early product news; ''Apply to be an Affiliate — applications are reviewed & accepted on an ongoing basis'' with an Apply Now button to Impact. Publishes affiliates@ritual.com and partnerships@ritual.com. No commission % or cap is published on this page (third-party reports conflict at 10%/20%/40%, so no rate is claimed).', 'verified', now());
