  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://seed.com/seeduniversity', 'brand_official_site', 'affiliate_program_page', 'Official SeedUniversity Partner Program page fetched in full: ''THIS IS NOT YOUR TYPICAL PARTNER PROGRAM'' for affiliates, ambassadors, micro/macro influencers; steps are Apply, Enroll (7-unit course + 100% final exam), then ''Seed the World'' with a unique code/URL plus one free month of DS-01. No commission rate, network, or earnings cap is published on this page. Page also lists practitioners@seed.com for its separate practitioner program.', 'verified', now());
